import numpy as np
from scipy.optimize import least_squares

_params = None

def _model(p, row):
    vmax, k_half, alpha_inh, c_leak = p
    u = float(row['u_now'])
    s = float(row['s_grad'])
    return vmax * u * u / (k_half + u * u) / (1.0 + alpha_inh * s) - c_leak * u

def fit(train_rows):
    global _params
    def residual(p):
        return np.array([_model(p, r) - float(r['y']) for r in train_rows])
    best = None
    for k in (0.3, 1.0, 3.0, 10.0):
        for alpha in (0.2, 1.0, 3.0):
            result = least_squares(residual, [7.0, k, alpha, 0.2], bounds=([0.0, 1e-9, 0.0, 0.0], [100.0, 100.0, 100.0, 10.0]), max_nfev=5000)
            if best is None or np.dot(result.fun, result.fun) < np.dot(best.fun, best.fun):
                best = result
    _params = best.x

def predict(row):
    return float(_model(_params, row))
